  ('zcrm_5797994000001857057', 'Eqore', 'Equore', 'Zachary Caporale', 'Jorge Nin', 'Small startup out of MIT incubator that uses company data to create a model for a plant''s energy usage, and uses that to automatically draw energy at optimal times, lowering costs incurred by straining the power grid at peak times.', 'HV STEM', NULL, 'Fall 2024', 'Ben Grosse', 'Reached Out', 'Zack Caporale', 'Rejected', NULL, 'Founder Communication (no response etc.)', NULL, '2024-10-29 08:24:52', '2024-12-08 16:44:13', '2024-12-08 16:44:13'),
