  ('zcrm_5797994000001936059', 'Omadeus', 'Omadeus', 'John Paul Oei', 'Massoud Alibakhsh', 'The world’s 1st AI-native project management powered by a dynamic network of self-aware AI agents', 'HV STEM', NULL, 'Fall 2024', NULL, 'Reached Out', 'JP', 'Rejected', NULL, NULL, NULL, '2024-11-12 16:44:18', '2025-08-26 07:45:14', '2025-08-26 07:45:14'),
  ('zcrm_5797994000001936083', 'Rarefied', 'Rarefied', 'John Paul Oei', 'Angela Feldhaus', 'Rarefied is developing a novel propulsion mechanism that allows lightweight platforms to fly in near-space (30-100 km) using only sunlight.', 'HV STEM', NULL, 'Fall 2024', NULL, 'Reached Out', 'JP', 'Rejected', NULL, NULL, NULL, '2024-11-12 16:51:50', '2025-08-26 07:45:14', '2025-08-26 07:45:14'),
  ('zcrm_5797994000001936107', 'Avol', 'Avol', 'John Paul Oei', 'Nate Poon', 'Avol enables medical centers to process lab samples up to 11x faster at lower cost by delivering samples using autonomous, long-range Avol drones.', 'HV STEM', NULL, 'Fall 2024', NULL, 'Reached Out', 'JP', 'Rejected', NULL, NULL, NULL, '2024-11-12 16:55:48', '2025-08-26 07:45:14', '2025-08-26 07:45:14'),
  ('zcrm_5797994000001936131', 'Scispot', 'Scispot', 'John Paul Oei', 'Guru Singh', 'Scispot: Transforming labs into AI powerhouses with LLM-powered middleware, ensuring seamless data integration, analysis, and accelerating scientific breakthroughs.', 'HV STEM', NULL, 'Fall 2024', NULL, 'Reached Out', 'JP', 'Rejected', NULL, NULL, NULL, '2024-11-12 17:17:18', '2025-08-26 07:45:14', '2025-08-26 07:45:14'),
  ('zcrm_5797994000001936163', 'Bifrost Orbital', 'Bifrost Orbital', 'John Paul Oei', 'Geffen Avraham', 'Bifrost Orbital is building the SSH for satellites, i.e., creating a network of satellites to ensure continuous, real-time communication for other satellites in space. Our technology allows customers to monitor and control their satellites 24/7, just like accessing a computer remotely. We offer reliable, low-power, and backward-compatible solutions that work for both small and large spacecraft, making space operations more efficient and connected.', 'HV STEM', NULL, 'Fall 2024', NULL, 'Reached Out', 'JP', 'Rejected', NULL, NULL, NULL, '2024-11-13 07:49:14', '2025-08-26 07:45:14', '2025-08-26 07:45:14'),
  ('zcrm_5797994000001936187', 'Forerunner AI', 'Forerunner AI', 'John Paul Oei', 'Yash Kadadi', 'Forerunner is your aerospace, defense, and hardware engineering copilot, helping you beat tight deadlines by automating critical engineering workflows. Our secure AI agents access data from tools like Atlassian Suite and Microsoft Office, then collaborate with hardware engineers to accelerate design and analysis.', 'HV STEM', NULL, 'Fall 2024', NULL, 'Reached Out', 'JP', 'Rejected', NULL, NULL, NULL, '2024-11-13 07:50:55', '2025-08-26 07:45:14', '2025-08-26 07:45:14'),
  ('zcrm_5797994000001936211', 'Innate', 'Innate', 'John Paul Oei', 'Axel Peytavin', 'Innate is developing the AI brain for teachable home robots. From navigation to manipulation, interaction and planning, our robots already act entirely autonomously, and users can teach entirely new behaviors quickly.
Our customers use them to do chores the way they want, starting with cleaning or serving humans.', 'HV STEM', NULL, 'Fall 2024', NULL, 'Reached Out', 'JP', 'Rejected', NULL, NULL, NULL, '2024-11-13 07:52:53', '2025-08-26 07:45:14', '2025-08-26 07:45:14'),
  ('zcrm_5797994000001936235', 'Fresco', 'Fresco', 'John Paul Oei', 'Arvind Veluvali', 'Fresco helps construction superintendents take 1000s of pages of notes, 10x faster. We automate the process of completing progress notes and punch lists, reducing time requirements from hours to minutes. Superintendents simply record videos of their site walk, and Fresco pulls out the relevant information and formats it into rich reports. We also offer one-click integrations with leading project management software like Procore and ACC, for maximum usability.', 'HV STEM', NULL, 'Fall 2024', NULL, 'Reached Out', 'JP', 'Rejected', NULL, NULL, NULL, '2024-11-13 07:58:48', '2025-08-26 07:45:14', '2025-08-26 07:45:14'),
  ('zcrm_5797994000001936259', 'Curo', 'Curo', 'John Paul Oei', 'Andrew Porter', 'Curo helps electric fleets park and charge their vehicles anywhere with the world’s largest private network of underutilized EV charging sites. We increase revenue by 5x for EV charger owners and enable instant fleet electrification at a fraction of the cost.', 'HV STEM', NULL, 'Fall 2024', NULL, 'Reached Out', 'JP', 'Rejected', NULL, NULL, NULL, '2024-11-13 08:15:56', '2025-08-26 07:45:14', '2025-08-26 07:45:14'),
  ('zcrm_5797994000001936283', 'Sensei', 'Sensei', 'John Paul Oei', 'Anubhav Guha', 'Sensei helps robotics companies scale and outsource their training data collection. Our hardware platform enables the collection of human-demonstration data at a tenth of the cost and twice the speed of current teleop approaches. Our software platform acts like Scale AI for robotics data: a large network of paid human operators use our low-cost collection platform to fulfill data-generation requests.', 'HV STEM', NULL, 'Fall 2024', NULL, 'Reached Out', 'JP', 'Rejected', NULL, NULL, NULL, '2024-11-13 08:24:27', '2025-08-26 07:45:14', '2025-08-26 07:45:14'),
  ('zcrm_5797994000001936307', 'Ember Robotics', 'Ember Robotics', 'John Paul Oei', 'Shivani Mouleeswaran', 'Ember Robotics is building the hardware observability layer for autonomous robots, starting with camera diagnostic tools. We worked on optimizing camera performance at Tesla Autopilot and now we''re building software that takes mitigating camera failures from hours to minutes.', 'HV STEM', NULL, 'Fall 2024', NULL, 'Reached Out', 'JP', 'Rejected', NULL, NULL, NULL, '2024-11-13 08:27:25', '2025-08-26 07:45:14', '2025-08-26 07:45:14'),
